import{_ as a,c as e,o as r,a5 as o}from"./chunks/framework.DYgWcJ6Z.js";const m=JSON.parse('{"title":"Trace 模块说明","description":"","frontmatter":{},"headers":[],"relativePath":"threepio/generate-domcument/trace/trace-zh.md","filePath":"threepio/generate-domcument/trace/trace-zh.md","lastUpdated":1751346917000}'),l={name:"threepio/generate-domcument/trace/trace-zh.md"};function i(c,t,d,n,s,h){return r(),e("div",null,t[0]||(t[0]=[o('<h1 id="trace-模块说明" tabindex="-1">Trace 模块说明 <a class="header-anchor" href="#trace-模块说明" aria-label="Permalink to &quot;Trace 模块说明&quot;">​</a></h1><h2 id="模块功能简介" tabindex="-1">模块功能简介 <a class="header-anchor" href="#模块功能简介" aria-label="Permalink to &quot;模块功能简介&quot;">​</a></h2><p>Threepio 的 trace（追踪）模块用于对整个 LLM 驱动的页面生成流程进行的流程追踪、性能分析和数据采集。它能够自动记录每个阶段（如规划、模块生成、DOM 操作等）的时间点、耗时、输入输出、异常等信息，</p><p>通过分析收集的信息，达成渐进式生成页面的目标。</p><h3 id="渐进式指标" tabindex="-1">渐进式指标 <a class="header-anchor" href="#渐进式指标" aria-label="Permalink to &quot;渐进式指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>含义描述</th><th>阈值</th></tr></thead><tbody><tr><td>PFP（Page Frame Paint）</td><td>页面/应用框架绘制</td><td>≤ 1.8s</td></tr><tr><td>CPI（Content Paint Interval）</td><td>页面内容生成间隔</td><td>≤ 300ms</td></tr></tbody></table><p>主要功能包括：</p><ul><li>自动追踪每个请求（如页面规划、模块生成、HTML 解析等）的开始、结束时间和耗时。</li><li>记录每个阶段的输入、输出、异常信息。</li><li>以结构化 trace 数据（如 trace.json）输出，便于后续分析和可视化。</li><li>支持多级嵌套追踪，完整还原 LLM 驱动的页面生成全流程。</li></ul><h2 id="如何使用-trace-模块" tabindex="-1">如何使用 trace 模块 <a class="header-anchor" href="#如何使用-trace-模块" aria-label="Permalink to &quot;如何使用 trace 模块&quot;">​</a></h2><ol><li><p><strong>自动集成</strong>： RequestFlowManager 等核心流程类已自动集成 trace，无需手动调用。使用 <code>startSpan</code>，对目标函数作为callback，trace 数据会自动采集。</p></li><li><p><strong>事件监听</strong>： 可通过监听 RequestFlowManager 的事件（如 <code>append</code>）获取每个阶段的追踪数据。</p></li><li><p><strong>trace 数据输出</strong>： 执行流程后，会在指定目录生成 trace.json 文件，包含所有阶段的详细追踪信息。</p></li></ol><h2 id="trace-数据结构说明" tabindex="-1">trace 数据结构说明 <a class="header-anchor" href="#trace-数据结构说明" aria-label="Permalink to &quot;trace 数据结构说明&quot;">​</a></h2><p>trace.json 主要包含：</p><table tabindex="0"><thead><tr><th>字段名</th><th>说明</th></tr></thead><tbody><tr><td>input</td><td>用户的输入</td></tr><tr><td>spans</td><td>每个阶段的追踪片段，含类型、开始/结束时间、异常、属性等</td></tr><tr><td>timePoints</td><td>关键时间点，便于分析各阶段耗时</td></tr><tr><td>callgraghs</td><td>大语言模型的请求的关系</td></tr></tbody></table><h2 id="如何用-trace-数据优化提示词" tabindex="-1">如何用 trace 数据优化提示词 <a class="header-anchor" href="#如何用-trace-数据优化提示词" aria-label="Permalink to &quot;如何用 trace 数据优化提示词&quot;">​</a></h2><ol><li><strong>分析耗时</strong>： <ul><li>通过分析 trace 的 spans ，可以定位 LLM 规划、模块生成 每个阶段的耗时瓶颈</li><li>通过分析 trace 的 timePoints ，DOM 操作阶段的耗时瓶颈。</li></ul></li><li><strong>定位异常</strong>：trace 会记录每个阶段的异常信息，便 于发现提示词不合理导致的 LLM 误解或输出异常。</li><li><strong>优化 prompt</strong>：根据 trace 发现的慢点或异常点，有针对性地调整 systemPrompt、workerPrompt 等提示词内容，提高 LLM 输出的准确性和效率。</li><li><strong>可视化分析</strong>：可将 trace.json 导入可视化工具，直观分析流程瓶颈和优化空间。</li></ol><h2 id="示例-trace-优化流程" tabindex="-1">示例：trace 优化流程 <a class="header-anchor" href="#示例-trace-优化流程" aria-label="Permalink to &quot;示例：trace 优化流程&quot;">​</a></h2><ol><li>执行页面生成，得到 trace.json。</li><li>发现 planRequest 阶段耗时较长，分析 systemPrompt，发现描述不够精炼。</li><li>优化 systemPrompt，缩短 LLM 响应时间。</li><li>重新执行，trace.json 显示耗时明显下降。</li></ol>',17)]))}const u=a(l,[["render",i]]);export{m as __pageData,u as default};
